package ru.alfabank.api.accounts.gateway;

import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import lombok.RequiredArgsConstructor;
import lombok.SneakyThrows;
import org.springframework.beans.factory.ObjectFactory;
import org.springframework.stereotype.Component;
import ru.alfabank.api.accounts.entity.CustomerAccountCreationRequest;
import ru.alfabank.api.accounts.dto.AccountResponseDto;
import ru.alfabank.ws.cs.eq.wsaccountnew11.WSAccountNew11PortType;
import ru.alfabank.ws.cs.eq.wsaccountnew11.WSAccountNewAddResponseType;
import ru.alfabank.ws.cs.eq.wsaccountnewinoutparms11.WSAccountNewAddInParms;
import ru.alfabank.ws.cs.wscommontypes10.WSCommonParms;

import java.util.Optional;

@Component
@RequiredArgsConstructor
public class AccountNewGateway {
    private static final String DEFAULT_MOD = "1";

    private final ObjectFactory<WSCommonParms> commonParms;
    private final WSAccountNew11PortType wsAccountNew11PortType;

    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public AccountResponseDto createCustomerAccount(CustomerAccountCreationRequest request) {
        WSAccountNewAddResponseType result = wsAccountNew11PortType.wsAccountNewAdd(this.getCommonParms(request),
                WSAccountNewAddInParms.builder()
                        .cus(request.getCus())
                        .ab(request.getBranch())
                        .act(request.getAccountType())
                        .ccy(request.getCurrencyCode())
                        .mod(DEFAULT_MOD)
                        .par(Optional.ofNullable(request.getPar()).map(o -> o ? "Y" : "N").orElse(null))
                        .res(Optional.ofNullable(request.getReservation()).map(o -> o ? "Y" : "N").orElse(null))
                        .build());
        return convert(result);
    }

    private AccountResponseDto convert(WSAccountNewAddResponseType from) {
        return new AccountResponseDto()
                .setAccountNumber(from.getOutParms().getEan())
                .setAccountIndex(from.getOutParms().getAs());
    }

    private WSCommonParms getCommonParms(CustomerAccountCreationRequest request) {
        WSCommonParms parms = commonParms.getObject();
        parms.setUserID(request.getUserId());
        return parms;
    }
}
```

