package ru.alfabank.api.accounts.gateway;

import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import lombok.RequiredArgsConstructor;
import lombok.SneakyThrows;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.ObjectFactory;
import org.springframework.stereotype.Component;
import ru.alfabank.api.accounts.entity.Account;
import ru.alfabank.ws.cs.eq.wsaccountbaseinfo10.WSAccountBaseInfoPortType;
import ru.alfabank.ws.cs.eq.wsaccountbaseinfoinoutparms10.WSAccountBaseInfoGetInParms;
import ru.alfabank.ws.cs.eq.wsaccountbaseinfoinoutparms10.WSAccountBaseInfoGetOutParms;
import ru.alfabank.ws.cs.wscommontypes10.WSCommonParms;

import java.time.ZoneId;
import java.util.Date;
import java.util.Optional;

import static ru.alfabank.api.converters.Converters.extractBoolean;

/**
 * Created by aashatunov on 25.05.2016.
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class AccountBaseInfoGateway {

    private final ObjectFactory<WSCommonParms> commonParms;
    private final WSAccountBaseInfoPortType wsAccountBaseInfoPortType;

    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public Account getAccountByNumber(String accountNumber) {
        return convert(wsAccountBaseInfoPortType.wsAccountBaseInfoGet(commonParms.getObject(),
                WSAccountBaseInfoGetInParms.builder()
                        .ean(accountNumber)
                        .build()));
    }

    private Account convert(WSAccountBaseInfoGetOutParms from) {
        return new Account()
                .setBranchId(from.getMainInfo().getAb())
                .setAccountNumber(from.getMainInfo().getEan())
                .setBaseCurrencyCode(from.getMainInfo().getCcy())
                .setOpenDate(Optional.ofNullable(from.getMainInfo().getOad())
                        .map(oad -> Date.from(oad.atStartOfDay(ZoneId.systemDefault()).toInstant()))
                        .orElse(null))
                .setCloseDate(Optional.ofNullable(from.getMainInfo().getCad())
                        .map(cad -> Date.from(cad.atStartOfDay(ZoneId.systemDefault()).toInstant()))
                        .orElse(null))
                .setAccountSuffix(from.getMainInfo().getAs())
                .setAccountingMode(from.getMainInfo().getBrg())
                .setAct(from.getMainInfo().getAct())
                .setAccountGroup(from.getMainInfo().getSac())
                .setPinEq(from.getMainInfo().getAn())
                .setAccountName(from.getMainInfo().getShn())
                .setResponsibleDeptCode(from.getMainInfo().getAco())
                .setOverdraftExpDate(from.getMainInfo().getLed())
                .setAccountModifyDate(from.getMainInfo().getDlm())
                .setAccountExCode(from.getAdditionalInfoACCLN().getIus())
                .setAccountMgrCode(from.getAdditionalInfoACCLN().getImn())
                .setMaxDocQueue(from.getAdditionalInfoACCLN().getDcmx())

                .setClientClosedC14(extractBoolean(from.getMainInfo().getAi14()))
                .setAccountBlockedC17(extractBoolean(from.getMainInfo().getAi17()))
                .setAccountClosedC30(extractBoolean(from.getMainInfo().getAi30()))
                .setLimitedDebitC82(extractBoolean(from.getMainInfo().getAi82()))
                .setDigitalCatalogC83(extractBoolean(from.getMainInfo().getAi83()))
                .setPaperCatalogC87(extractBoolean(from.getMainInfo().getAi87()))
                .setInActiveAccountC20(extractBoolean(from.getMainInfo().getAi20()))
                .setCanNotDebitedC12(extractBoolean(from.getMainInfo().getAi12()))
                .setCanNotCreditC11(extractBoolean(from.getMainInfo().getAi11()));
    }

}
