package ru.alfabank.api.accounts.gateway;

import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.SneakyThrows;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.springframework.beans.factory.ObjectFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import ru.alfabank.api.accounts.configuration.OperationType;
import ru.alfabank.api.accounts.entity.Account;
import ru.alfabank.api.accounts.entity.BankInfo;
import ru.alfabank.api.accounts.mapper.CustomerAccountListGBAGetParamsMapper;
import ru.alfabank.api.accounts.mapper.CustomerAccountListGBAGetParamsMapper.OperationTypeDto;
import ru.alfabank.api.customer.migration.products.FormerAccount;
import ru.alfabank.ws.cs.wscommontypes10.WSCommonParms;
import ru.alfabank.ws.eq.uwscustomeraccountlistgba29.UWSCustomerAccountListGBA29PortType;
import ru.alfabank.ws.eq.uwscustomerbaseinfo16.UWSCustomerBaseInfo16PortType;
import ru.alfabank.ws.eq.uwscustomerbaseinfoinoutparms16.UWSCustomerBaseInfoGetInParms;
import ru.alfabank.ws.eq.uwscustomerbaseinfoinoutparms16.UWSCustomerBaseInfoGetOutParms;

import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Created by aashatunov on 27.02.2017.
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class AccountListGbaGateway {

    private final ObjectFactory<WSCommonParms> commonParms;
    private final UWSCustomerAccountListGBA29PortType accountListPortType;
    private final UWSCustomerBaseInfo16PortType uwsCustomerBaseInfo16PortType;

    private final CodeMigrationBanksGateway codeMigrationBanksGateway;
    private final CustomerMigrationProductsGateway customerMigrationProductsGateway;

    private final CustomerAccountListGBAGetParamsMapper getParamsMapper;

    @Value("${WSCustomerAccountListGBA.language_name_mnemonic:}")
    private String lnm;

    @Value("${pickMigrationBank:false}")
    private boolean pickMigrationBank;

    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public List<Account> getAccountListByPinEqAndActIn(String pinEq, OperationType operationType, String[] acts, boolean useNewBalance, String[] accountNumbers) {
        List<Account> result = getParamsMapper.mapToAccountsList(accountListPortType.uwsCustomerAccountListGBAGet(commonParms.getObject(),
                        getParamsMapper.mapToGetParams(pinEq, new OperationTypeDto(operationType, acts, accountNumbers), lnm, useNewBalance))
                        .getOutParms()
                        .getResultSet()
                        .getResultSetRow(), useNewBalance);

        if (pickMigrationBank) {
            fillMigrationBankInfo(pinEq, result);
        }

        return result;
    }

    @SneakyThrows
    private void fillMigrationBankInfo(String pinEq, List<Account> accounts) {

        UWSCustomerBaseInfoGetInParms inParms = new UWSCustomerBaseInfoGetInParms();
        inParms.setCus(pinEq);

        if (isMigrateBank(uwsCustomerBaseInfo16PortType.uwsCustomerBaseInfoGet(commonParms.getObject(), inParms).getOutParms())) {
            fillMigrationAccounts(customerMigrationProductsGateway.getMigrationAccounts(pinEq), accounts);
        }
    }

    private void fillMigrationAccounts(List<FormerAccount> formerAccounts, List<Account> accounts) {
        Map<String, MigrationProduct> migrationProducts = new HashMap<>();
        for (final FormerAccount fa : formerAccounts) {
            migrationProducts.put(
                    fa.getAccountNumber(),
                    new MigrationProduct(fa.getMigrationBankCode(), fa.getMigrationDate().toLocalDate()));
        }

        if (!migrationProducts.isEmpty()) {
            for (Account acc : accounts) {
                if (migrationProducts.containsKey(acc.getAccountNumber())) {
                    MigrationProduct bank = migrationProducts.get(acc.getAccountNumber());
                    acc.setMigrationBankCode(bank.getMigrationBankCode());
                    acc.setMigrationBankName(getBankName(bank.getMigrationBankCode()));
                    acc.setMigrationDate(bank.getMigrationDate());
                }
            }
        }
    }

    private boolean isMigrateBank(UWSCustomerBaseInfoGetOutParms outParms) {
        return "Y".equals(outParms.getMigrb());
    }

    private String getBankName(String code) {
        if (StringUtils.isEmpty(code)) {
            return null;
        }

        try {
            return codeMigrationBanksGateway.getMigrationBanks().stream()
                    .filter(bankInfo -> code.equalsIgnoreCase(bankInfo.getCode()))
                    .findFirst()
                    .map(BankInfo::getName)
                    .orElse(code);
        } catch (Exception e) {
            log.error("couldn't load migration bank catalog");
            return code;
        }
    }

    @Getter
    @AllArgsConstructor
    private static class MigrationProduct {
        private final String migrationBankCode;
        private final LocalDate migrationDate;
    }
}
```

