    public static final Function<String, String> ACCOUNT_NUMBER_VALUE_EXTRACTOR = Function.identity();
    public static final Function<BalanceType, String> BALANCE_TYPE_VALUE_EXTRACTOR = BalanceType::getCode;

    private final ObjectFactory<WSCommonParms> commonParms;
