        List<CardAccountType> cardAccountTypes = convert(wsCardAccountTypeCardContractListPortType
                .wsCardAccountTypeCardContractListGet(commonParms.getObject(), inParms));

        if (CollectionUtils.isNotEmpty(restrictAccountTypes)) {
            cardAccountTypes = cardAccountTypes.stream()
                    .filter(at -> !restrictAccountTypes.contains(at.getType()))
                    .collect(Collectors.toList());
