package ru.alfabank.api.accounts.gateway;

import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;
import lombok.RequiredArgsConstructor;
import lombok.SneakyThrows;
import org.springframework.beans.factory.ObjectFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import ru.alfabank.api.accounts.entity.CustomerAccountTypes;
import ru.alfabank.ws.cs.eq.wscustomernewaccounttypes11.WSCustomerNewAccountTypes11PortType;
import ru.alfabank.ws.cs.eq.wscustomernewaccounttypes11.WSCustomerNewAccountTypesGetResponseType;
import ru.alfabank.ws.cs.eq.wscustomernewaccounttypesinoutparms11.WSCustomerNewAccountTypesGetInParms;
import ru.alfabank.ws.cs.eq.wscustomernewaccounttypesinoutparms11.WSCustomerNewAccountTypesGetOutCurrenciesRecordSetRow;
import ru.alfabank.ws.cs.eq.wscustomernewaccounttypesinoutparms11.WSCustomerNewAccountTypesGetOutRecordSetRow;
import ru.alfabank.ws.cs.wscommontypes10.WSCommonParms;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

@Component
@RequiredArgsConstructor
public class CustomerNewAccountTypesGateway {
    @Value("${was.wscustomernewaccounttypes.externalSystem}")
    private String externalSystem;

    private final ObjectFactory<WSCommonParms> commonParms;
    private final WSCustomerNewAccountTypes11PortType wsCustomerNewAccountTypes11PortType;

    @SneakyThrows
    @CircuitBreaker(name = "wsCircuitBreaker")
    public CustomerAccountTypes getCustomerAccountTypes(String cus) {
        WSCustomerNewAccountTypesGetResponseType result = wsCustomerNewAccountTypes11PortType.wsCustomerNewAccountTypesGet(commonParms.getObject(),
                WSCustomerNewAccountTypesGetInParms.builder()
                        .cus(cus)
                        .xm(externalSystem)
                        .build());

        return convert(result);
    }

    private CustomerAccountTypes convert(WSCustomerNewAccountTypesGetResponseType from) {
        CustomerAccountTypes result = new CustomerAccountTypes();

        List<CustomerAccountTypes.AccountType> accountTypeList = new ArrayList<>();
        for (WSCustomerNewAccountTypesGetOutRecordSetRow row : from.getOutParms().getResultSet().getRecordSetRow()) {
            CustomerAccountTypes.AccountType accountType = new CustomerAccountTypes.AccountType()
                    .setType(row.getAtp())
                    .setName(row.getAtn())
                    .setCurrencies(getTypeCurrencyList(row.getCurrencies().getTypesRecordSetRow()));

            accountTypeList.add(accountType);
        }
        result.setTypes(accountTypeList);

        return result;
    }

    private List<CustomerAccountTypes.TypeCurrency> getTypeCurrencyList(List<WSCustomerNewAccountTypesGetOutCurrenciesRecordSetRow> from) {
        return from.stream()
                .map(item -> new CustomerAccountTypes.TypeCurrency(item.getCcy()))
                .collect(Collectors.toList());
    }
}
